return "    #获取订单信息\n    get_order_info 3801 {\n        response {\n            .orderneed {\n                needitem 0 : integer\n                neednum  2 : integer\n            }\n            .order { \n                id       0 : integer    #订单id\n                quality  1 : integer    #订单品质\n                dropid   2 : string     #订单奖励\n                needlist 3 : *orderneed #订单需求\n            }\n            result    0 : integer\n            orderlist 1 : *order\n            lasttime  2 : string\n        }\n    }\n\n    #删除一个订单\n    delete_order_by_index 3802 {\n        request {\n            index 0 : integer\n        }\n        response {\n            result 0 : integer\n        }\n    }\n\n    #完成一个订单\n    get_order_reward_by_index 3803 {\n        request {\n            index 0 : integer\n        }\n        response {\n            result    0 : integer\n            costitems 1 : *costs\n            gold      2 : integer\n            diamond   3 : integer\n            items     4 : *item\n        }\n    }\n\n    #立即刷新一个订单\n    refsh_order_right_now 3804 {\n        response {\n            result    0 : integer\n            costitems 1 : *costs\n        }\n    }\n\n    set_new_order 3805 {\n        response {\n            result    0 : integer\n        }\n    }\n"
